command:
query=query($owner:String!, $name:String!) {
 repository(owner:$owner,name:$name) {
  issues(first:60,states:OPEN,orderBy:{field:UPDATED_AT,direction:DESC}) {
   nodes { number title labels(first:12) { nodes { name } }
    timelineItems(last:30,itemTypes:[CONNECTED_EVENT,DISCONNECTED_EVENT]) { nodes {
      __typename
      ... on ConnectedEvent { id createdAt source { ...peer } subject { ...peer } }
      ... on DisconnectedEvent { id createdAt source { ...peer } subject { ...peer } }
    } }
   }
  }
 }
}
fragment peer on ReferencedSubject {
 __typename
 ... on Issue { number repository { nameWithOwner } }
 ... on PullRequest { number state title body headRefName baseRefName repository { nameWithOwner } }
}
